<?php
declare(strict_types=1);
namespace Modules\Integrations;
use App\{DB,Http,Auth};

final class RegistryView
{
    private static function columns(string $p): array {if($p==='onec')return ['number'=>'Номер','date_display'=>'Дата','amount'=>'Сумма','status'=>'Статус','file_status'=>'Файлы','key'=>'Идентификатор'];if($p==='diadoc')return ['date_display'=>'Дата','title'=>'Наименование','document_type'=>'Вид','sender'=>'Отправитель','recipient'=>'Получатель','status'=>'Статус','file_status'=>'Файлы','key'=>'Идентификатор'];if($p==='bank')return ['date_display'=>'Дата','number'=>'Номер','bank_payer'=>'Плательщик','bank_organization'=>'Наша организация','bank_account'=>'Расчётный счёт','amount'=>'Поступило','bank_purpose'=>'Назначение платежа','bank_operation'=>'Операция'];return ['date_display'=>'Дата / период','number'=>'Номер','account_display'=>'Счёт / объект','address'=>'Адрес','amount'=>'Сумма','status'=>'Статус','file_status'=>'Файлы','key'=>'Идентификатор'];}
    public static function render(string $p): string {
        $db=DB::pdo();$e=Support::e(...);$qText=trim((string)($_GET['q']??''));$where='d.provider=?';$args=[$p];if($qText!==''){$where.=' AND (d.number LIKE ? OR d.title LIKE ? OR d.source_id LIKE ? OR d.account_id LIKE ? OR x.search_text LIKE ?)';for($i=0;$i<5;$i++)$args[]='%'.$qText.'%';}$q=$db->prepare('SELECT COUNT(*) FROM external_documents d LEFT JOIN external_document_details x ON x.document_id=d.id WHERE '.$where);$q->execute($args);$count=(int)$q->fetchColumn();$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*50;$q=$db->prepare('SELECT d.*,x.account_display,x.address,x.sender,x.recipient,x.document_type,x.bank_payer,x.bank_organization,x.bank_account,x.bank_purpose,x.bank_operation FROM external_documents d LEFT JOIN external_document_details x ON x.document_id=d.id WHERE '.$where.' ORDER BY d.document_date DESC,d.source_id LIMIT 50 OFFSET '.$offset);$q->execute($args);$rows=$q->fetchAll(\PDO::FETCH_ASSOC);$columns=self::columns($p);$profiles=json_decode(file_get_contents(__DIR__.'/defaults/table-profiles.json'),true)['profiles'];$profile=$profiles['connection-'.$p]??[];$profile=array_map(static fn($v)=>$v['key']==='type'?array_replace($v,['key'=>'document_type']):($v['key']==='account'?array_replace($v,['key'=>'account_display']):$v),$profile);$h='<section class="table-card registry-ui-card registry-ui-sticky-table registry-ui-sticky-table--wide-scroll registry-ui-scroll" data-registry-id="connection-records"><div class="table-toolbar registry-ui-toolbar"><div class="registry-ui-checkboxes"><span class="found-label">Записей: <b id="record-count">'.$count.'</b> · показано: <b id="visible-count">'.count($rows).'</b></span></div><div class="toolbar-right">';if($p!=='onec'){$h.='<div class="demo-row" id="result-downloads"'.(!$count?' hidden':'').'>';foreach(['zip'=>'Скачать всё','html'=>'Отчёт','csv'=>'CSV','json'=>'JSON'] as $type=>$label)$h.='<a class="btn btn-toolbar" href="/integrations/export?provider='.$p.'&amp;type='.$type.'">'.$label.'</a>';$h.='</div>';}$h.='<form method="get" class="registry-ui-search-group"><input type="search" class="toolbar-search registry-ui-search" name="q" value="'.$e($qText).'" placeholder="Поиск по полученному набору" aria-label="Поиск по полученным данным"></form></div></div><div class="table-scroll" id="connection-data-scroll" role="region" tabindex="0" aria-label="Полученные записи"><table class="table registry-ui-table registry-ui-data registry-ui-data--columns" data-column-profile="connection-'.$p.'"'.($profile?' data-column-spec="'.$e(Support::json($profile)).'"':'').'><thead><tr>';foreach($columns as $label)$h.='<th scope="col">'.$label.'</th>';$h.='</tr></thead><tbody id="records-body">';foreach($rows as $d){$q=$db->prepare('SELECT COUNT(*) FROM external_files WHERE document_id=?');$q->execute([$d['id']]);$files=(int)$q->fetchColumn()+count(array_filter(CaptureFiles::forDocument($db,$d['id']),static fn($f)=>$f['available']));$h.='<tr tabindex="0" data-record-url="?document='.$e($d['id']).'" aria-label="Открыть сведения о документе '.$e($d['number']).'">';foreach($columns as $key=>$label){$value=match($key){'date_display'=>date('d.m.Y',strtotime($d['document_date'])),'key'=>$d['source_id'],'file_status'=>$files?'Получено: '.$files:'Не получены','amount'=>self::money($d['amount']),default=>$d[$key]??'—'};$h.='<td>'.($key==='number'||$key==='key'?'<a href="?document='.$e($d['id']).'">'.$e($value?:'Не указано').'</a>':$e($value?:'Не указано')).'</td>';}$h.='</tr>';}if(!$rows)$h.='<tr><td colspan="'.count($columns).'">Нет данных.</td></tr>';$h.='</tbody></table></div>';if($offset+50<$count||$page>1){$h.='<nav class="pagination" aria-label="Продолжение реестра"><div class="inline-actions">';if($page>1)$h.='<a class="btn btn-toolbar" href="?q='.rawurlencode($qText).'&amp;page='.($page-1).'">Назад</a>';if($offset+50<$count)$h.='<a class="btn btn-toolbar" href="?q='.rawurlencode($qText).'&amp;page='.($page+1).'">Далее</a>';$h.='</div></nav>';}$h.='</section>';
        $q=$db->prepare("SELECT coverage_json FROM integration_runs WHERE provider=? AND operation='import' AND status='success' ORDER BY created_at DESC LIMIT 1");$q->execute([$p]);$coverage=json_decode($q->fetchColumn()?:'{}',true);if($count)$h.='<div class="demo-row" id="connection-notes"><span class="registry-ui-secondary" id="probe-coverage">'.(($coverage['complete']??false)?'Полный обход указанного периода подтверждён.':'Полнота архива не подтверждена; импортированы только полученные записи.').'</span></div>';
        if(isset($_GET['document']))$h.=self::detail($p,(string)$_GET['document']);return $h;
    }
    public static function money(?string $value): string {if($value===null)return 'Не указано';$negative=str_starts_with($value,'-');$v=ltrim($value,'-');[$whole,$fraction]=array_pad(explode('.',$v,2),2,'');$whole=preg_replace('/\B(?=(\d{3})+(?!\d))/u',' ',$whole);$fraction=rtrim($fraction,'0');$fraction=str_pad($fraction,2,'0');return ($negative?'-':'').$whole.','.$fraction;}
    private static function detail(string $p,string $id): string {
        $e=Support::e(...);$db=DB::pdo();$q=$db->prepare('SELECT * FROM external_documents WHERE id=? AND provider=?');$q->execute([$id,$p]);$d=$q->fetch(\PDO::FETCH_ASSOC);if(!$d)throw new \RuntimeException('Документ не найден',404);$raw=Support::decode(Config::store()->read($d['raw_path'],$d['raw_sha256']));$h='<dialog class="modal registry-ui-modal registry-ui-modal--reading ui-detail-card" id="connection-record" aria-labelledby="connection-record-title"><div class="modal-head"><h2 class="modal-title" id="connection-record-title">'.$e($d['title'].' '.$d['number']).'</h2><button type="button" class="modal-close" data-dialog-close aria-label="Закрыть поля записи">×</button></div><div class="modal-body registry-ui-modal-grid"><div id="record-fields" class="registry-ui-modal-grid registry-ui-modal-grid--reading">';foreach(Details::flatten($raw) as $field)$h.='<div class="field"><span class="field-label">'.$e($field['label']).'</span><span class="registry-ui-modal-text">'.$e($field['value']).'</span></div>';$h.='</div></div><div class="modal-foot"><div class="modal-foot-actions" id="record-footer-actions">';$q=$db->prepare('SELECT * FROM external_files WHERE document_id=? ORDER BY created_at DESC');$q->execute([$id]);foreach($q as $f)$h.='<a class="btn btn-secondary" href="/integrations/file?id='.$e($f['id']).'&amp;provider='.$p.'">'.$e($f['filename']).'</a>'; $h.=CaptureFiles::links($db,$id,$p);if(PageView::canEdit($p,'integrations.write')&&in_array($p,['diadoc','pik','mosvodokanal','mosenergo'],true)){foreach($p==='diadoc'?['pdf'=>'Получить PDF','original'=>'Получить оригинал']:['pdf'=>'Получить PDF'] as $kind=>$label)$h.='<form method="post" action="/integrations/action"><input type="hidden" name="_csrf" value="'.$e(Http::csrf()).'"><input type="hidden" name="action" value="fetch_file"><input type="hidden" name="provider" value="'.$p.'"><input type="hidden" name="request_key" value="'.Support::uuid().'"><input type="hidden" name="document_id" value="'.$e($id).'"><input type="hidden" name="kind" value="'.$kind.'"><button class="btn btn-secondary" type="submit">'.$label.'</button></form>';}$h.='<button type="button" class="btn btn-secondary" data-dialog-close>Закрыть</button></div></div></dialog><script>document.getElementById("connection-record").showModal();</script>';return $h;
    }
}
